From 585a34b92f22824329a91ba89749bc4b3e48ae34 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:12:48 +0100
Subject: [PATCH] applets/pager: Drag a stand-in instead of the window outline
 itself

Dragging reparented the outline and every release reset the model, so a
dropped outline flashed back on its old desktop until KWin moved it.
Drag a separate rectangle that stays where it was dropped until then.

BUG: 524124
---
 applets/pager/qml/main.qml | 83 +++++++++++++++++++++++++-------------
 1 file changed, 56 insertions(+), 27 deletions(-)

diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..8be059387a 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -238,6 +238,26 @@ PlasmoidItem {
         dragTimer.restart();
     }

+    // Stand-in for the window outline being dragged, so the real outline stays in its desktop
+    // and the model never has to be reset to put it back
+    Rectangle {
+        id: dragProxy
+
+        // The outline being dragged, or dropped and waiting for its window to leave its desktop
+        property Item source: null
+
+        visible: source !== null
+        z: 1000
+        border.width: 1
+
+        // In case the window doesn't move after all
+        Timer {
+            id: dropTimeout
+            interval: 1000
+            onTriggered: dragProxy.source = null
+        }
+    }
+
     Grid {
         id: pagerItemGrid

@@ -498,6 +518,7 @@ PlasmoidItem {
                             width: Math.round(geometry.width * pagerItemGrid.widthScaleFactor)
                             height: Math.round(geometry.height * pagerItemGrid.heightScaleFactor)
                             visible: Plasmoid.configuration.showWindowOutlines && !minimized
+                            opacity: dragProxy.source === windowRect ? 0 : 1
                             color: {
                                 if (desktop.isCurrent) {
                                     if (isActive) {
@@ -523,13 +544,23 @@ PlasmoidItem {
                                 id: windowMouseArea
                                 anchors.fill: parent

-                                drag.target: windowRect
+                                drag.target: dragProxy
                                 drag.threshold: 1
                                 drag.axis: Drag.XAndYAxis
                                 drag.minimumX: 0
-                                drag.maximumX: root.width - windowRect.width
+                                drag.maximumX: root.width - dragProxy.width
                                 drag.minimumY: 0
-                                drag.maximumY: root.height - windowRect.height
+                                drag.maximumY: root.height - dragProxy.height
+
+                                onPressed: mouse => {
+                                    const topLeft = windowRect.mapToItem(root, 0, 0);
+                                    dragProxy.x = topLeft.x;
+                                    dragProxy.y = topLeft.y;
+                                    dragProxy.width = windowRect.width;
+                                    dragProxy.height = windowRect.height;
+                                    dragProxy.color = windowRect.color;
+                                    dragProxy.border.color = windowRect.border.color;
+                                }

                                 drag.onActiveChanged: {
                                     root.dragging = drag.active;
@@ -537,38 +568,36 @@ PlasmoidItem {
                                     desktopMouseArea.enabled = !drag.active;

                                     if (drag.active) {
-                                        // Reparent to allow drags outside of this desktop.
-                                        const value = root.mapFromItem(clipRect, windowRect.x, windowRect.y);
-                                        windowRect.parent = root;
-                                        windowRect.x = value.x;
-                                        windowRect.y = value.y;
+                                        dropTimeout.stop();
+                                        dragProxy.source = windowRect;
                                     }
                                 }

                                 onReleased: mouse => {
-                                    if (root.dragging) {
-                                        windowRect.visible = false;
-                                        const windowCenter = Qt.point(windowRect.x + windowRect.width / 2, windowRect.y + windowRect.height / 2);
-                                        const pagerItem = pagerItemGrid.childAt(windowCenter.x, windowCenter.y) as DesktopDelegate;
-
-                                        if (pagerItem) {
-                                            const relativeTopLeft = root.mapToItem(pagerItem, windowRect.x, windowRect.y);
-
-                                            const modelIndex = windowRectRepeater.model.index(windowRect.index, 0)
-                                            pagerModel.moveWindow(modelIndex, relativeTopLeft.x, relativeTopLeft.y,
-                                                pagerItem.desktopId, root.dragId,
-                                                pagerItemGrid.widthScaleFactor, pagerItemGrid.heightScaleFactor);
-                                        }
-
-                                        // Will reset the model, destroying the reparented drag delegate that
-                                        // is no longer bound to model.Geometry.
-                                        root.dragging = false;
-                                    } else {
+                                    if (!root.dragging) {
                                         // When there is no dragging (just a click), the event is passed
                                         // to the desktop MouseArea.
                                         desktopMouseArea.clicked(mouse);
+                                        return;
+                                    }
+
+                                    const proxyCenter = Qt.point(dragProxy.x + dragProxy.width / 2, dragProxy.y + dragProxy.height / 2);
+                                    const pagerItem = pagerItemGrid.childAt(proxyCenter.x, proxyCenter.y) as DesktopDelegate;
+
+                                    // Windows on all desktops can't be moved to one
+                                    const canMove = root.isActivityPager || !windowRect.model.IsOnAllVirtualDesktops;
+                                    if (pagerItem && pagerItem.desktopId !== root.dragId && canMove) {
+                                        const relativeTopLeft = root.mapToItem(pagerItem, dragProxy.x, dragProxy.y);
+                                        const modelIndex = windowRectRepeater.model.index(windowRect.index, 0);
+                                        pagerModel.moveWindow(modelIndex, relativeTopLeft.x, relativeTopLeft.y,
+                                            pagerItem.desktopId, root.dragId,
+                                            pagerItemGrid.widthScaleFactor, pagerItemGrid.heightScaleFactor);
+                                        // Keep showing the stand-in where it was dropped until this outline goes away
+                                        // (which clears dragProxy.source) because the window left this desktop
+                                        dropTimeout.restart();
+                                    } else {
+                                        dragProxy.source = null;
                                     }
-                                    pagerModel.refresh();
                                 }
                             }

-- 
2.53.0
